    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"تعريف المحيط","math":"المحيط هو مجموع أطوال جميع الأضلاع"},{"quoi":"نجمع الأضلاع","math":"<span dir=\"ltr\" class=\"expr\">P = x + x + x + 8 + (x + 5)</span>"},{"quoi":"نزيل الأقواس","math":"<span dir=\"ltr\" class=\"expr\">P = x + x + x + 8 + x + 5</span>"},{"quoi":"نجمع حدود x","math":"مجموع حدود x يساوي 4 x"},{"quoi":"نجمع الأعداد","math":"مجموع الأعداد يساوي 13"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = 4 x + 13</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نعوّض في العبارة","math":"<span dir=\"ltr\" class=\"expr\">P = 4 × <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> + 13</span>"},{"quoi":"نحسب الجداء","math":"<span dir=\"ltr\" class=\"expr\">4 × <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> = 1</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">1 + 13 = 14</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = 14</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">4 x + 13 = 33</span>"},{"quoi":"نطرح 13 من الطرفين","math":"<span dir=\"ltr\" class=\"expr\">4 x = 33 - 13</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">33 - 13 = 20</span>"},{"quoi":"نقسم على 4","math":"<span dir=\"ltr\" class=\"expr\">x = 20 : 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 5</span>"}],
