    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"تعريف المحيط","math":"المحيط هو مجموع أطوال جميع الأضلاع"},{"quoi":"نجمع الأضلاع","math":"<span dir=\"ltr\" class=\"expr\">P = x + (x + 3) + x + 9</span>"},{"quoi":"نزيل الأقواس","math":"<span dir=\"ltr\" class=\"expr\">P = x + x + 3 + x + 9</span>"},{"quoi":"نجمع حدود x","math":"مجموع حدود x يساوي 3 x"},{"quoi":"نجمع الأعداد","math":"مجموع الأعداد يساوي 12"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = 3 x + 12</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نعوّض في العبارة","math":"<span dir=\"ltr\" class=\"expr\">P = 3 × 6 + 12</span>"},{"quoi":"نحسب الجداء","math":"<span dir=\"ltr\" class=\"expr\">3 × 6 = 18</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">18 + 12 = 30</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = 30</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">3 x + 12 = <span class=\"frac\"><span class=\"num\">51</span><span class=\"den\">4</span></span></span>"},{"quoi":"نطرح 12 من الطرفين","math":"<span dir=\"ltr\" class=\"expr\">3 x = <span class=\"frac\"><span class=\"num\">51</span><span class=\"den\">4</span></span> - 12</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">51</span><span class=\"den\">4</span></span> - 12 = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span></span>"},{"quoi":"نقسم على 3","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> : 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span></span>"}],
