    enonce: "<span class=\"q\">1) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">9a + 4b = 261</span> و <span dir=\"ltr\" class=\"expr\">ab = 378</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 7(3a + 2b) - 3(a + 2b)</span> ثمّ جد قيمتها العددية<br><span class=\"q\">2) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">9a + 4b = 261</span> و <span dir=\"ltr\" class=\"expr\">ab = 378</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 7(3a + 2b) - 3(a + 2b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 54a + 24b + 54</span> ثمّ جد قيمتها العددية<br><span class=\"q\">3) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">9a + 4b = 261</span> و <span dir=\"ltr\" class=\"expr\">ab = 378</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 7(3a + 2b) - 3(a + 2b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 54a + 24b + 54</span> احسب القيمة العددية للعبارة <span dir=\"ltr\" class=\"expr\">G = (a + 4)(b + 9)</span><br><span class=\"q\">4) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">9a + 4b = 261</span> و <span dir=\"ltr\" class=\"expr\">ab = 378</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 7(3a + 2b) - 3(a + 2b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 54a + 24b + 54</span> احسب القيمة العددية للعبارة جد العددين a و b علما أنّ الفرق بينهما يساوي 3",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"ننشر القوسين","math":"<span dir=\"ltr\" class=\"expr\">7(3a + 2b) - 3(a + 2b) = 21a + 14b - 3a - 6b</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">21a + 14b - 3a - 6b = 21a - 3a + 14b - 6b</span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\">21a + 14b - 3a - 6b = 18a + 8b</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">18a + 8b = 2(9a + 4b)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">2(9a + 4b) = 2 × 261</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = 522</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نبحث عن عامل مشترك","math":"الأعداد 54 و 24 و 54 كلّها مضاعفات لـ 6"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">54a + 24b + 54 = 6(9a + 4b + 9)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">9a + 4b = 261</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">261 + 9 = 270</span>"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">6 × 270 = 1620</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 1620</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننشر جداء القوسين","math":"<span dir=\"ltr\" class=\"expr\">(a + 4)(b + 9) = ab + 9a + 4b + 36</span>"},{"quoi":"نجمع المعطيات","math":"<span dir=\"ltr\" class=\"expr\">ab = 378</span> و <span dir=\"ltr\" class=\"expr\">9a + 4b = 261</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">ab + 9a + 4b + 36 = 378 + 261 + 36</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">378 + 261 + 36 = 675</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">G = 675</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نترجم المعطى الجديد","math":"<span dir=\"ltr\" class=\"expr\">a - b = 3</span> إذن <span dir=\"ltr\" class=\"expr\">a = b + 3</span>"},{"quoi":"نعوّض في المساواة","math":"<span dir=\"ltr\" class=\"expr\">9(b + 3) + 4b = 261</span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">9b + 27 + 4b = 261</span>"},{"quoi":"نجمع حدود b","math":"<span dir=\"ltr\" class=\"expr\">13b + 27 = 261</span>"},{"quoi":"نعزل حدّ b","math":"<span dir=\"ltr\" class=\"expr\">13b = 261 - 27</span>"},{"quoi":"نحسب b","math":"<span dir=\"ltr\" class=\"expr\">b = 234 : 13 = 18</span>"},{"quoi":"نحسب a","math":"<span dir=\"ltr\" class=\"expr\">a = b + 3 = 21</span>"}],
