    enonce: "<span class=\"q\">1) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">4a + 5b = 57</span> و <span dir=\"ltr\" class=\"expr\">ab = 40</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 2(6a + 9b) - 4(a + 2b)</span> ثمّ جد قيمتها العددية<br><span class=\"q\">2) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">4a + 5b = 57</span> و <span dir=\"ltr\" class=\"expr\">ab = 40</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 2(6a + 9b) - 4(a + 2b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 16a + 20b + 12</span> ثمّ جد قيمتها العددية<br><span class=\"q\">3) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">4a + 5b = 57</span> و <span dir=\"ltr\" class=\"expr\">ab = 40</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 2(6a + 9b) - 4(a + 2b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 16a + 20b + 12</span> احسب القيمة العددية للعبارة <span dir=\"ltr\" class=\"expr\">G = (a + 5)(b + 4)</span><br><span class=\"q\">4) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">4a + 5b = 57</span> و <span dir=\"ltr\" class=\"expr\">ab = 40</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 2(6a + 9b) - 4(a + 2b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 16a + 20b + 12</span> احسب القيمة العددية للعبارة جد العددين a و b علما أنّ الفرق بينهما يساوي 3",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"ننشر القوسين","math":"<span dir=\"ltr\" class=\"expr\">2(6a + 9b) - 4(a + 2b) = 12a + 18b - 4a - 8b</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">12a + 18b - 4a - 8b = 12a - 4a + 18b - 8b</span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\">12a + 18b - 4a - 8b = 8a + 10b</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">8a + 10b = 2(4a + 5b)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">2(4a + 5b) = 2 × 57</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = 114</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نبحث عن عامل مشترك","math":"الأعداد 16 و 20 و 12 كلّها مضاعفات لـ 4"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">16a + 20b + 12 = 4(4a + 5b + 3)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">4a + 5b = 57</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">57 + 3 = 60</span>"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">4 × 60 = 240</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 240</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننشر جداء القوسين","math":"<span dir=\"ltr\" class=\"expr\">(a + 5)(b + 4) = ab + 4a + 5b + 20</span>"},{"quoi":"نجمع المعطيات","math":"<span dir=\"ltr\" class=\"expr\">ab = 40</span> و <span dir=\"ltr\" class=\"expr\">4a + 5b = 57</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">ab + 4a + 5b + 20 = 40 + 57 + 20</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">40 + 57 + 20 = 117</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">G = 117</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نترجم المعطى الجديد","math":"<span dir=\"ltr\" class=\"expr\">a - b = 3</span> إذن <span dir=\"ltr\" class=\"expr\">a = b + 3</span>"},{"quoi":"نعوّض في المساواة","math":"<span dir=\"ltr\" class=\"expr\">4(b + 3) + 5b = 57</span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">4b + 12 + 5b = 57</span>"},{"quoi":"نجمع حدود b","math":"<span dir=\"ltr\" class=\"expr\">9b + 12 = 57</span>"},{"quoi":"نعزل حدّ b","math":"<span dir=\"ltr\" class=\"expr\">9b = 57 - 12</span>"},{"quoi":"نحسب b","math":"<span dir=\"ltr\" class=\"expr\">b = 45 : 9 = 5</span>"},{"quoi":"نحسب a","math":"<span dir=\"ltr\" class=\"expr\">a = b + 3 = 8</span>"}],
