  { id: "expr7-7-3", chapitre: "expr7", chapitreNom: "العبارات الحرفية", niveau: 7,
    rubrique: "ex7", rubriqueNom: "عددان طبيعيان تحت شرط", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">3a + 6b = 216</span> و <span dir=\"ltr\" class=\"expr\">ab = 640</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 6(2a + 8b) - 6(a + 6b)</span> ثمّ جد قيمتها العددية<br><span class=\"q\">2) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">3a + 6b = 216</span> و <span dir=\"ltr\" class=\"expr\">ab = 640</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 6(2a + 8b) - 6(a + 6b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 15a + 30b + 45</span> ثمّ جد قيمتها العددية<br><span class=\"q\">3) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">3a + 6b = 216</span> و <span dir=\"ltr\" class=\"expr\">ab = 640</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 6(2a + 8b) - 6(a + 6b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 15a + 30b + 45</span> احسب القيمة العددية للعبارة <span dir=\"ltr\" class=\"expr\">G = (a + 6)(b + 3)</span><br><span class=\"q\">4) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">3a + 6b = 216</span> و <span dir=\"ltr\" class=\"expr\">ab = 640</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 6(2a + 8b) - 6(a + 6b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 15a + 30b + 45</span> احسب القيمة العددية للعبارة جد العددين a و b علما أنّ الفرق بينهما يساوي 12",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"ننشر القوسين","math":"<span dir=\"ltr\" class=\"expr\">6(2a + 8b) - 6(a + 6b) = 12a + 48b - 6a - 36b</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">12a + 48b - 6a - 36b = 12a - 6a + 48b - 36b</span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\">12a + 48b - 6a - 36b = 6a + 12b</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">6a + 12b = 2(3a + 6b)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">2(3a + 6b) = 2 × 216</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = 432</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نبحث عن عامل مشترك","math":"الأعداد 15 و 30 و 45 كلّها مضاعفات لـ 5"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">15a + 30b + 45 = 5(3a + 6b + 9)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">3a + 6b = 216</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">216 + 9 = 225</span>"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">5 × 225 = 1125</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 1125</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننشر جداء القوسين","math":"<span dir=\"ltr\" class=\"expr\">(a + 6)(b + 3) = ab + 3a + 6b + 18</span>"},{"quoi":"نجمع المعطيات","math":"<span dir=\"ltr\" class=\"expr\">ab = 640</span> و <span dir=\"ltr\" class=\"expr\">3a + 6b = 216</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">ab + 3a + 6b + 18 = 640 + 216 + 18</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">640 + 216 + 18 = 874</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">G = 874</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نترجم المعطى الجديد","math":"<span dir=\"ltr\" class=\"expr\">a - b = 12</span> إذن <span dir=\"ltr\" class=\"expr\">a = b + 12</span>"},{"quoi":"نعوّض في المساواة","math":"<span dir=\"ltr\" class=\"expr\">3(b + 12) + 6b = 216</span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">3b + 36 + 6b = 216</span>"},{"quoi":"نجمع حدود b","math":"<span dir=\"ltr\" class=\"expr\">9b + 36 = 216</span>"},{"quoi":"نعزل حدّ b","math":"<span dir=\"ltr\" class=\"expr\">9b = 216 - 36</span>"},{"quoi":"نحسب b","math":"<span dir=\"ltr\" class=\"expr\">b = 180 : 9 = 20</span>"},{"quoi":"نحسب a","math":"<span dir=\"ltr\" class=\"expr\">a = b + 12 = 32</span>"}],
    indice: "بعد النشر ستظهر العبارة 3a + 6b التي نعرف قيمتها" }
